// Generated by the /ship test coverage audit (Claude).
// Value: protects=the production router registers the shared error page, not-found page and PostHog capture for every route;
//   fails_when=a default is removed so routes fall back to TanStack's built-in error UI or errors stop being reported;
//   why_new=error-boundary.test builds its own router, so nothing asserts getRouter() wires the defaults it relies on;
//   seam=none; no_claim=real route rendering or PostHog delivery (options only; server functions are not called).
// Value (strengthened): protects=an error thrown by a route loader or component, rendered through getRouter(), reaches PostHog as that same Error and shows the error page; a 404 is not reported;
//   fails_when=defaultOnCatch is unwired or no longer receives the route error, or not-found starts being reported as an exception;
//   why_new=the options-identity test passes even if TanStack stops calling defaultOnCatch, so a real error is driven end to end;
//   seam=none; no_claim=the real app route tree and PostHog delivery (routeTree.gen is replaced by a tiny tree; posthog-js is mocked).
import { cleanup, render, screen } from "@testing-library/react";
import { RouterProvider } from "@tanstack/react-router";
import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
import { DefaultErrorPage } from "@/app/error";
import { DefaultNotFoundPage } from "@/app/not-found";
import { captureRouteError } from "@integrations/posthog/capture";
import { getRouter } from "@/router";

const mocks = vi.hoisted(() => ({
  posthog: { __loaded: true, captureException: vi.fn() },
  loaderError: new Error("Feed failed"),
  renderError: new Error("Reader crashed"),
}));

// posthog-js is installed under apps/web only, so the mock addresses it by path like capture.test.ts.
vi.mock("../../../../apps/web/node_modules/posthog-js", () => ({ default: mocks.posthog }));

// The real route tree pulls in every module and server function; getRouter() itself stays real.
vi.mock("@/routeTree.gen", async () => {
  const { Outlet, createRootRoute, createRoute } = await import("@tanstack/react-router");
  const root = createRootRoute({ component: () => <Outlet /> });
  const home = createRoute({
    getParentRoute: () => root,
    path: "/",
    component: () => <p>Home content</p>,
  });
  const loaderFailure = createRoute({
    getParentRoute: () => root,
    path: "/loader-failure",
    loader: () => {
      throw mocks.loaderError;
    },
    component: () => <p>Loader content</p>,
  });
  const renderFailure = createRoute({
    getParentRoute: () => root,
    path: "/render-failure",
    component: () => {
      throw mocks.renderError;
    },
  });

  return { routeTree: root.addChildren([home, loaderFailure, renderFailure]) };
});

function renderRouterAt(path: string) {
  window.history.replaceState(null, "", path);
  return render(<RouterProvider router={getRouter()} />);
}

beforeEach(() => {
  mocks.posthog.__loaded = true;
  mocks.posthog.captureException.mockReset();
  vi.spyOn(console, "error").mockImplementation(() => undefined);
  vi.spyOn(console, "warn").mockImplementation(() => undefined);
});

afterEach(() => {
  cleanup();
  window.history.replaceState(null, "", "/");
  vi.restoreAllMocks();
});

describe("getRouter", () => {
  test("registers the router-wide error, not-found and capture defaults", () => {
    const { options } = getRouter();

    expect(options.defaultErrorComponent).toBe(DefaultErrorPage);
    expect(options.defaultNotFoundComponent).toBe(DefaultNotFoundPage);
    expect(options.defaultOnCatch).toBe(captureRouteError);
  });

  test.each([
    ["a failing loader", "/loader-failure", () => mocks.loaderError],
    ["a component that throws while rendering", "/render-failure", () => mocks.renderError],
  ] as const)("reports %s to PostHog and shows the error page", async (_name, path, getError) => {
    renderRouterAt(path);

    expect(await screen.findByText("We lost the plot")).toBeTruthy();
    expect(mocks.posthog.captureException).toHaveBeenCalled();
    for (const [reported] of mocks.posthog.captureException.mock.calls) {
      expect(reported).toBe(getError());
    }
  });

  test("shows not-found for an unknown path without reporting an exception", async () => {
    renderRouterAt("/does-not-exist");

    expect(await screen.findByText("Page not found")).toBeTruthy();
    expect(mocks.posthog.captureException).not.toHaveBeenCalled();
  });

  test("renders a healthy route without reporting anything", async () => {
    renderRouterAt("/");

    expect(await screen.findByText("Home content")).toBeTruthy();
    expect(mocks.posthog.captureException).not.toHaveBeenCalled();
  });
});
